import xarray as xrimport numpy as npclass AzimuthEstimator:    def __init__(self, latitude, longitude, tilt, lookup_table):        self.latitude = latitude        self.longitude = longitude        self.tilt = tilt        self.ds = xr.load_dataset(lookup_table)    def estimate(self, omega_star, doy):            curve = self.ds["omega_star"].sel(doy=doy)            idx = np.argmin(            np.abs(curve.data - omega_star)        )            azimuth = curve.azimuth[idx].item()            return azimuth